export const DBGVALUE = (
		value: unknown,
		label: string = 'VALUE'
		): void => {

	const str = nice(value)
	if (str.includes('\n')) {
		DBG(f`${label}:{blue} =`)
		DBG(indented(str))
	}
	else {
		DBG(f`${label}:{blue} = ${nice(value)}`)
	}
	return
}

